class Vec:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __add__(self, other):
        return Vec(self.x + other.x, self.y + other.y)
    def __sub__(self, other):
        return Vec(self.x - other.x, self.y - other.y)
    def __mul__(self, k):
        return Vec(self.x * k, self.y * k)
    def __repr__(self):
        return ('(' + str(self.x) + ',' + str(self.y) + ')')
v1 = Vec(1, 2)
v2 = Vec(3, 4)
print(v1 + v2)
print(v2 - v1)
print(v1 * 3)
print((v1 + v2) == Vec(4, 6), v1 == v2)

